      "Keep recovery copies and quit": "\u30EA\u30AB\u30D0\u30EA\u30B3\u30D4\u30FC\u3092\u4FDD\u6301\u3057\u3066\u7D42\u4E86",
      "Keep running": "\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u3067\u5B9F\u884C\u3092\u7D9A\u3051\u308B",
      "Keep saved version": "\u4FDD\u5B58\u6E08\u307F\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u4FDD\u6301",
