      Shanghai: "\u4E0A\u6D77",
      Shape: "\u30B7\u30A7\u30A4\u30D7",
      Shapes: "\u30B7\u30A7\u30A4\u30D7",
      "Shapes (R)": "\u30B7\u30A7\u30A4\u30D7\uFF08R\uFF09",
      Share: "\u5171\u6709",
      "Share my memory": "\u81EA\u5206\u306E\u30E1\u30E2\u30EA\u3092\u5171\u6709",
      "Share of tracked cost": "\u628A\u63E1\u6E08\u307F\u8CBB\u7528\u306E\u5272\u5408",
      "Share this page so the agent can read and use it": "\u3053\u306E\u30DA\u30FC\u30B8\u3092\u5171\u6709\u3059\u308B\u3068\u3001Agent \u304C\u8AAD\u307F\u53D6\u308A\u3084\u64CD\u4F5C\u3092\u884C\u3048\u307E\u3059",
      "Share with agent": "Agent \u3068\u5171\u6709",
