      "Load task": "\uC791\uC5C5 \uBD88\uB7EC\uC624\uAE30",
      "Load this range": "\uC774 \uBC94\uC704 \uBD88\uB7EC\uC624\uAE30",
      "Load view": "\uBCF4\uAE30 \uBD88\uB7EC\uC624\uAE30",
      "Loaded tools": "\uBD88\uB7EC\uC628 \uB3C4\uAD6C",
      Loading: "\uBD88\uB7EC\uC624\uB294 \uC911",
      "Loading documents": "\uBB38\uC11C \uBD88\uB7EC\uC624\uB294 \uC911",
      "Loading image\u2026": "\uC774\uBBF8\uC9C0 \uBD88\uB7EC\uC624\uB294 \uC911\u2026",
      "Loading knowledge": "\uC9C0\uC2DD \uBCA0\uC774\uC2A4 \uBD88\uB7EC\uC624\uB294 \uC911",
      "Loading knowledge bases\u2026": "\uC9C0\uC2DD \uBCA0\uC774\uC2A4 \uBD88\uB7EC\uC624\uB294 \uC911\u2026",
      "Loading knowledge scope\u2026": "\uC9C0\uC2DD \uBC94\uC704 \uBD88\uB7EC\uC624\uB294 \uC911\u2026",
      "Loading live captions\u2026": "\uC2E4\uC2DC\uAC04 \uC790\uB9C9 \uBD88\uB7EC\uC624\uB294 \uC911\u2026",
      "Loading meetings": "\uD68C\uC758 \uBD88\uB7EC\uC624\uB294 \uC911",
      "Loading models\u2026": "\uBAA8\uB378 \uBD88\uB7EC\uC624\uB294 \uC911\u2026",
